import sqlite3
from flask import Flask, request

app = Flask(__name__)

@app.get('/user')
def user():
    name = request.args.get('name', '')
    connection = sqlite3.connect(':memory:')
    query = "SELECT id FROM users WHERE name = '%s'" % name
    return str(connection.execute(query).fetchall())

import sqlite3
from flask import Flask, request

app = Flask(__name__)

@app.get('/user')
def user():
    name = request.args.get('name', '')
    connection = sqlite3.connect(':memory:')
    cursor = connection.cursor()
    cursor.execute('SELECT id FROM users WHERE name = ?', (name,))
    return str(cursor.fetchall())

const express = require('express');
const { exec } = require('child_process');
const app = express();

app.get('/search', (req, res) => {
  exec('grep ' + req.query.term + ' /var/log/aegis.log', (error, stdout) => res.send(stdout));
});

const express = require('express');
const { execFile } = require('child_process');
const app = express();

app.get('/status', (req, res) => {
  const args = req.query.action === 'version' ? ['--version'] : ['status'];
  execFile('/usr/bin/git', args, (error, stdout) => res.send(stdout));
});

const express = require('express');
const app = express();

app.get('/calculate', (req, res) => {
  const result = eval(req.query.expression);
  res.json({ result });
});

const express = require('express');
const app = express();

app.get('/parse', (req, res) => {
  const value = JSON.parse(String(req.query.value || '{}'));
  res.json(value);
});
